create extension if not exists pgcrypto;

create table if not exists public.admin_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null default 'admin' check (role in ('admin','editor')),
  created_at timestamptz not null default now()
);

create table if not exists public.creators (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  handle text not null,
  status text not null default 'Available now',
  bio text not null default '',
  expanded_bio text,
  avatar_image text not null default '',
  cover_image text not null default '',
  badges jsonb not null default '[]'::jsonb,
  stats jsonb not null default '{}'::jsonb,
  subscription jsonb not null default '{}'::jsonb,
  tabs jsonb not null default '{}'::jsonb,
  published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.creator_posts (
  id uuid primary key default gen_random_uuid(),
  creator_id uuid not null references public.creators(id) on delete cascade,
  type text not null check (type in ('image','video')),
  title text not null,
  caption text not null default '',
  media_url text not null,
  thumbnail_url text,
  published boolean not null default false,
  reels_enabled boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.post_likes (
  post_id uuid not null references public.creator_posts(id) on delete cascade,
  user_id uuid references auth.users(id) on delete cascade,
  visitor_key text,
  created_at timestamptz not null default now(),
  primary key (post_id, user_id, visitor_key),
  check (user_id is not null or visitor_key is not null)
);

create table if not exists public.post_comments (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.creator_posts(id) on delete cascade,
  user_id uuid references auth.users(id) on delete set null,
  visitor_key text,
  body text not null check (char_length(body) between 1 and 1000),
  created_at timestamptz not null default now(),
  check (user_id is not null or visitor_key is not null)
);

create table if not exists public.post_views (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.creator_posts(id) on delete cascade,
  user_id uuid references auth.users(id) on delete set null,
  visitor_key text,
  created_at timestamptz not null default now(),
  check (user_id is not null or visitor_key is not null)
);

create index if not exists creator_posts_creator_created_idx on public.creator_posts (creator_id, created_at desc);
create index if not exists creator_posts_reels_idx on public.creator_posts (reels_enabled, published, created_at desc);
create index if not exists post_comments_post_created_idx on public.post_comments (post_id, created_at desc);
create index if not exists post_views_post_created_idx on public.post_views (post_id, created_at desc);

create or replace function public.is_admin() returns boolean language sql security definer set search_path = public as $$
  select exists (select 1 from public.admin_roles where user_id = auth.uid());
$$;

create or replace function public.set_updated_at() returns trigger language plpgsql as $$
begin new.updated_at = now(); return new; end; $$;

drop trigger if exists creators_set_updated_at on public.creators;
create trigger creators_set_updated_at before update on public.creators for each row execute function public.set_updated_at();
drop trigger if exists creator_posts_set_updated_at on public.creator_posts;
create trigger creator_posts_set_updated_at before update on public.creator_posts for each row execute function public.set_updated_at();

alter table public.admin_roles enable row level security;
alter table public.creators enable row level security;
alter table public.creator_posts enable row level security;
alter table public.post_likes enable row level security;
alter table public.post_comments enable row level security;
alter table public.post_views enable row level security;

drop policy if exists creators_public_read on public.creators;
create policy creators_public_read on public.creators for select using (published = true or public.is_admin());
drop policy if exists creators_admin_write on public.creators;
create policy creators_admin_write on public.creators for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists posts_public_read on public.creator_posts;
create policy posts_public_read on public.creator_posts for select using (published = true or public.is_admin());
drop policy if exists posts_admin_write on public.creator_posts;
create policy posts_admin_write on public.creator_posts for all using (public.is_admin()) with check (public.is_admin());

drop policy if exists likes_public_read on public.post_likes;
create policy likes_public_read on public.post_likes for select using (true);
drop policy if exists likes_public_insert on public.post_likes;
create policy likes_public_insert on public.post_likes for insert with check (user_id = auth.uid() or (user_id is null and visitor_key is not null));
drop policy if exists likes_public_delete on public.post_likes;
create policy likes_public_delete on public.post_likes for delete using (user_id = auth.uid() or (user_id is null and visitor_key is not null));

drop policy if exists comments_public_read on public.post_comments;
create policy comments_public_read on public.post_comments for select using (true);
drop policy if exists comments_public_insert on public.post_comments;
create policy comments_public_insert on public.post_comments for insert with check (user_id = auth.uid() or (user_id is null and visitor_key is not null));
drop policy if exists comments_owner_delete on public.post_comments;
create policy comments_owner_delete on public.post_comments for delete using (user_id = auth.uid() or public.is_admin());

drop policy if exists views_public_insert on public.post_views;
create policy views_public_insert on public.post_views for insert with check (user_id = auth.uid() or (user_id is null and visitor_key is not null));
drop policy if exists views_admin_read on public.post_views;
create policy views_admin_read on public.post_views for select using (public.is_admin());
